function sortTable(n) {
  const table = document.querySelector("table");
  const rows = Array.from(table.querySelectorAll("tbody tr"));
  const header = table.querySelector("thead tr");
  const isAsc = header.querySelector("th:nth-child(" + (n + 1) + ")").classList.contains("asc");

  // Remove existing sort classes
  header.querySelectorAll("th").forEach(th => {
    th.classList.remove("asc", "desc");
  });

  // Toggle sort direction
  if (isAsc) {
    header.querySelector("th:nth-child(" + (n + 1) + ")").classList.add("desc");
  } else {
    header.querySelector("th:nth-child(" + (n + 1) + ")").classList.add("asc");
  }

  // Sort the rows
  rows.sort((a, b) => {
    const aVal = a.querySelectorAll("td")[n].textContent;
    const bVal = b.querySelectorAll("td")[n].textContent;

    if (isAsc) {
      return aVal.localeCompare(bVal);
    } else {
      return bVal.localeCompare(aVal);
    }
  });

  // Clear the table body
  const tbody = document.getElementById("tableBody");
  tbody.innerHTML = "";

  // Append the sorted rows
  rows.forEach(row => tbody.appendChild(row));
}
```

